+import { Component, EventEmitter, Input, Output } from '@angular/core';
+import { MatIconModule } from '@angular/material/icon';
+import { MatCardModule } from '@angular/material/card';
+import { MatButtonModule } from '@angular/material/button';
+import { ClinicService } from '../service/clinic.service';
+import { CustomService } from '@/app/shared/service/custom.service';
+import { forkJoin } from 'rxjs';
+
+@Component({
+  selector: 'app-clinic-view',
+  standalone: true,
+  imports: [MatIconModule, MatCardModule,
+    MatButtonModule,],
+  templateUrl: './clinic-view.component.html',
+  styleUrl: './clinic-view.component.scss'
+})
+export class ClinicViewComponent {
+
+  private currentClinicId: string | null = null;
+  @Output() close = new EventEmitter<void>();
+
+  @Input()
+  set clinicId(value: string | null) {
+    this.currentClinicId = value;
+    if (value) {
+      this.fetchClinicDetails(value); // Trigger API call when clinicId changes
+    }
+  }
+
+  get clinicId(): string | null {
+    return this.currentClinicId;
+  }
+
+  clinicData:any;
+  countryArray: any[] = [];
+  stateArray: any[] = [];
+  cityArray: any[] = [];
+  constructor(private clinicService: ClinicService, private customService: CustomService,) {
+
+  }
+
+  ngOnInit() {
+    this.getCountryData();
+  }
+
+  fetchClinicDetails(id: string): void {
+    this.clinicService.getClinicData(this.clinicId).subscribe((clinic: any) => {
+      this.clinicData = clinic;
+      // Load states and cities together
+      forkJoin({
+        states: this.customService.getStateList(clinic.country),
+        cities: this.customService.getCityList(clinic.state),
+      }).subscribe(({ states, cities }) => {
+        this.stateArray = states;
+        this.cityArray = cities;
+      });
+    });
+  }
+
+    getCountryData() {
+    this.customService.getCountryList().subscribe(country => {
+      this.countryArray = country;
+    });
+  }
+
+  getCountryName(id:Number){
+    const country = this.countryArray.find((obj:any)=>obj.id == id);
+    return country?.name;
+  }
+
+  getStateName(id:Number){
+    const state = this.stateArray.find((obj:any)=>obj.id == id);
+    return state?.name;
+  }
+
+  getCityName(id:Number){
+    const city = this.cityArray.find((obj:any)=>obj.id == id);
+    return city?.name;
+  }
+  
+  closeDialog(): void {
+    this.close.emit(); // Emit the close event to the parent
+  }
+
+}
