+// role.guard.ts
+import { Injectable } from '@angular/core';
+import { CanActivate, ActivatedRouteSnapshot, RouterStateSnapshot, Router } from '@angular/router';
+import { AuthenticationService } from '../service/auth.service';
+
+@Injectable({
+  providedIn: 'root'
+})
+export class AuthGuard implements CanActivate {
+  constructor(private auth: AuthenticationService, private router: Router) {}
+
+  canActivate(
+    next: ActivatedRouteSnapshot,
+    state: RouterStateSnapshot): boolean {
+
+        const token = this.auth.getAuthenticationToken();
+  
+  if (!token) {
+    this.router.navigate(['/auth/log-in']);
+    return false;
+  }
+
+  // 2. Ensure roles are loaded
+  if (!this.auth.user?.roles?.length) {
+    this.auth.loadUserFromStorage();
+  }
+
+  // 3. Then check roles (original logic)
+  const requiredRoles = next.data['roles'] || [];
+  if (this.auth.isAdmin()) return true;
+  
+  if (!requiredRoles.some((role:any) => this.auth.hasRole(role))) {
+    this.router.navigate(['/not-found']); // Better UX than redirecting to login
+    return false;
+  }
+
+  return true;
+  }
+}
