+  imports: [CommonModule],
+  template: `
+    <div class="d-flex align-items-center gap-2">
+      <div class="avatar-circle" *ngIf="!clinicImage">
+        <span class="avatar-initials">{{ initials }}</span>
+      </div>
+      <img *ngIf="clinicImage" [src]="clinicImage" class="avatar-image" alt="Clinic" />
+      <div>
+        <div class="fw-semibold">{{ clinicName }}</div>
+        <div class="text-muted small">{{ clinicEmail }}</div>
+      </div>
+    </div>
+  `,
+  styles: [`
+    .avatar-circle {
+      width: 36px;
+      height: 36px;
