+      text-transform: uppercase;
+    }
+    .fw-semibold { font-weight: 600; }
+    .text-muted { color: #888; }
+    .small { font-size: 12px; }
+    .gap-2 { gap: 0.5rem; }
+    .d-flex { display: flex; }
+    .align-items-center { align-items: center; }
+  `]
+})
+export class ClinicCellRendererComponent implements ICellRendererAngularComp {
+  params: any;
+  initials: string = '?';
+  clinicName: string = 'Loading...';
+  clinicEmail: string = '';
+  clinicImage: string | null = null;
+  private apiUrl = environment.serverUrl;
+  
+  constructor(private customService: CustomService) {}
+
+  agInit(params: ICellRendererParams): void {
+    this.params = params;
+    console.log('Clinic cell data:', params.data);
+    
+    // Check if we have direct clinic data
+    if (params.data?.clinic?.name) {
+      this.clinicName = params.data.clinic.name;
+      this.clinicEmail = params.data.clinic.email || '';
+      this.initials = this.getInitials(params.data.clinic.name);
+      
+      // Handle clinic image
+      this.handleClinicImage(params.data.clinic);
+      return;
+    }
+    
+    // Get clinic_id from the data
+    const clinicId = params.data?.clinic_id;
+    
+    if (clinicId) {
+      // Fetch clinic details using the clinic_id
+      this.customService.getClinicById(clinicId).subscribe(
+        (clinic: any) => {
+          if (clinic) {
+            this.clinicName = clinic.name || 'Unknown Clinic';
+            this.clinicEmail = clinic.email || '';
+            this.initials = this.getInitials(clinic.name);
+            
+            // Handle clinic image
+            this.handleClinicImage(clinic);
+          } else {
+            this.clinicName = 'Clinic Not Found';
+            this.initials = '?';
+            this.clinicImage = null;
+          }
+        },
+        (error) => {
+          console.error('Error fetching clinic:', error);
+          this.clinicName = 'Error Loading Clinic';
+          this.initials = '!';
+          this.clinicImage = null;
+        }
+      );
+    } else {
+      this.clinicName = 'No Clinic Assigned';
+      this.initials = '?';
+      this.clinicImage = null;
+    }
+  }
+
+  refresh(params: ICellRendererParams): boolean {
+    this.agInit(params);
+    return true;
+  }
+  
+  handleClinicImage(clinic: any): void {
+    if (clinic?.image || clinic?.profile_image) {
+      const imageUrl = clinic.image || clinic.profile_image;
+      
+      // Check if the image URL is already a complete URL
+      if (imageUrl.startsWith('http')) {
+        this.clinicImage = imageUrl;
+      } else if (imageUrl.startsWith('/')) {
+        // If it starts with a slash, just append to API URL
+        this.clinicImage = `${this.apiUrl}${imageUrl}`;
+      } else {
+        // Otherwise, prepend the API URL with a slash
+        this.clinicImage = `${this.apiUrl}/${imageUrl}`;
+      }
+      console.log('Clinic image URL:', this.clinicImage);
+    } else {
+      this.clinicImage = null;
+    }
+  }
+
+  getInitials(name: string): string {
+    if (!name) return '?';
+    const parts = name.split(' ');
+    if (parts.length === 1) return parts[0][0];
+    return parts[0][0] + parts[1][0];
+  }
+} 
