+export class NameCellRendererComponent implements ICellRendererAngularComp {
+  params: any;
+  initials: string = '';
+  displayName: string = '';
+  displayEmail: string = '';
+  profileImage: string | null = null;
+  private apiUrl = environment.serverUrl;
+
+  agInit(params: ICellRendererParams): void {
+    this.params = params;
+    console.log('Name cell data:', params.data);
+    this.updateDisplayValues();
+  }
+
+  refresh(params: ICellRendererParams): boolean {
+    this.params = params;
+    this.updateDisplayValues();
+    return true;
+  }
+  
+  updateDisplayValues(): void {
+    const data = this.params.data;
+    
+    // Handle name
+    if (data?.name) {
+      this.displayName = data.name;
+      this.initials = this.getInitials(data.name);
+    } else if (data?.first_name || data?.last_name) {
+      this.displayName = `${data.first_name || ''} ${data.last_name || ''}`.trim();
+      this.initials = this.getInitials(this.displayName);
+    } else {
+      this.displayName = 'Unknown';
+      this.initials = '?';
+    }
+    
+    // Handle email
+    this.displayEmail = data?.email || '';
+    
+    // Handle profile image
+    if (data?.profile_image) {
+      // Check if the image URL is already a complete URL
+      if (data.profile_image.startsWith('http')) {
+        this.profileImage = data.profile_image;
+      } else if (data.profile_image.startsWith('/')) {
+        // If it starts with a slash, just append to API URL
+        this.profileImage = `${this.apiUrl}${data.profile_image}`;
+      } else {
+        // Otherwise, prepend the API URL with a slash
+        this.profileImage = `${this.apiUrl}/${data.profile_image}`;
+      }
+      console.log('Profile image URL:', this.profileImage);
+    } else {
+      this.profileImage = null;
+    }
+  }
+
+  getInitials(name: string): string {
+    if (!name) return '?';
+    const parts = name.split(' ');
+    if (parts.length === 1) return parts[0][0];
+    return parts[0][0] + parts[1][0];
+  }
