+import { CommonModule } from '@angular/common';
+import { Component } from '@angular/core';
+import { ICellRendererAngularComp } from 'ag-grid-angular';
+import { ICellRendererParams } from 'ag-grid-community';
+import { ReceptionistService } from '../service/receptionist.service';
+import { FormsModule } from '@angular/forms';
+
+@Component({
+  selector: 'app-status-toggle-cell-renderer',
+  standalone: true,
+  imports: [CommonModule, FormsModule],
+  template: `
+    <label class="switch">
+      <input type="checkbox" [checked]="isActive" (change)="toggleStatus($event)">
+      <span class="slider round"></span>
+    </label>
+  `,
+  styles: [`
+    .switch {
+      position: relative;
+      display: inline-block;
+      width: 40px;
+      height: 22px;
+    }
+    .switch input { 
+      opacity: 0;
+      width: 0;
+      height: 0;
+    }
+    .slider {
+      position: absolute;
+      cursor: pointer;
+      top: 0; left: 0; right: 0; bottom: 0;
+      background-color: #ccc;
+      transition: .4s;
+      border-radius: 22px;
+    }
+    .slider:before {
+      position: absolute;
+      content: "";
+      height: 18px;
+      width: 18px;
+      left: 2px;
+      bottom: 2px;
+      background-color: white;
+      transition: .4s;
+      border-radius: 50%;
+    }
+    input:checked + .slider {
+      background-color: #5670cc;
+    }
+    input:checked + .slider:before {
+      transform: translateX(18px);
+    }
+    .slider.round {
+      border-radius: 22px;
+    }
+    .slider.round:before {
+      border-radius: 50%;
+    }
+  `]
+})
+export class StatusToggleCellRendererComponent implements ICellRendererAngularComp {
+  params: any;
+  isActive: boolean = false;
+  
+  constructor(private receptionistService: ReceptionistService) {}
+
+  agInit(params: ICellRendererParams): void { 
+    this.params = params;
+    this.isActive = this.getStatusValue();
+  }
+  
+  refresh(params: ICellRendererParams): boolean { 
+    this.params = params;
+    this.isActive = this.getStatusValue();
+    return true; 
+  }
+  
+  getStatusValue(): boolean {
+    const data = this.params.data;
+    if (data) {
+      if (typeof data.status === 'boolean') {
+        return data.status;
+      } else if (typeof data.status === 'number') {
+        return data.status === 1;
+      } else if (typeof data.status === 'string') {
+        return data.status.toLowerCase() === 'active' || 
+               data.status.toLowerCase() === 'true' || 
+               data.status === '1';
+      }
+    }
+    return false;
+  }
+
+  toggleStatus(event: any): void {
+    const newStatus = event.target.checked;
+    const receptionistId = this.params.data.id;
+    if (!receptionistId) return;
+    this.receptionistService.getReceptionistData(receptionistId).subscribe(
+      (receptionist: any) => {
+        const updatedData = {
+          ...receptionist,
+          status: newStatus ? 1 : 0
+        };
+        this.receptionistService.updateReceptionistData(receptionistId, updatedData).subscribe(
+          () => {
+            if (this.params.context && this.params.context.componentParent) {
+              this.params.context.componentParent.getReceptionistData();
+            }
+          }
+        );
+      }
+    );
+  }
