+
+@Component({
+  selector: 'app-verification-badge-cell-renderer',
+  standalone: true,
+  imports: [CommonModule],
+  template: `
+    <span [ngClass]="badgeClass">{{ verificationText }}</span>
+  `,
+  styles: [`
+    .badge {
+      border-radius: 6px;
+      padding: 4px 12px;
+      font-size: 14px;
+      font-weight: 500;
+      display: inline-block;
+    }
+    .badge-verified {
+      background: #e6f4ea;
+      color: #219653;
+    }
+    .badge-pending {
+      background: #fff8e6;
+      color: #f2994a;
+    }
+    .badge-unverified {
+      background: #fbe9e7;
+      color: #d32f2f;
+    }
+  `]
+})
+export class VerificationBadgeCellRendererComponent implements ICellRendererAngularComp {
+  verificationText: string = 'Verified';
+  badgeClass: string = 'badge badge-verified';
+  
+  agInit(params: ICellRendererParams): void {
+    console.log('Verification cell data:', params.data);
+    this.updateVerificationStatus(params.data);
+  }
+  
+  refresh(params: ICellRendererParams): boolean { 
+    this.updateVerificationStatus(params.data);
+    return true; 
+  }
+  
+  updateVerificationStatus(data: any): void {
+    // Default to verified if no verification field
+    if (!data || data.verification === undefined) {
+      this.verificationText = 'Verified';
+      this.badgeClass = 'badge badge-verified';
+      return;
+    }
+    
+    const status = data.verification;
+    
+    if (status === true || status === 1 || status === '1' || 
+        (typeof status === 'string' && status.toLowerCase() === 'verified')) {
+      this.verificationText = 'Verified';
+      this.badgeClass = 'badge badge-verified';
+    } else if (status === false || status === 0 || status === '0' || 
+               (typeof status === 'string' && status.toLowerCase() === 'unverified')) {
+      this.verificationText = 'Unverified';
+      this.badgeClass = 'badge badge-unverified';
+    } else if (typeof status === 'string' && status.toLowerCase() === 'pending') {
+      this.verificationText = 'Pending';
+      this.badgeClass = 'badge badge-pending';
+    } else {
+      this.verificationText = 'Verified';
+      this.badgeClass = 'badge badge-verified';
+    }
+  }
