+import { Injectable } from '@angular/core';
+import { environment } from '@/environments/environment';
+import { HttpClient } from '@angular/common/http';
+import { map, Observable } from 'rxjs';
+
+@Injectable({
+  providedIn: 'root'
+})
+export class ReceptionistService {
+
+  private apiUrl = environment.serverUrl;
+  
+    
+  constructor(protected http: HttpClient) { }
+
+  getReceptionistList(): Observable<any> {
+    return this.http
+      .get<any>(`${this.apiUrl}/admin/receptionists`, { observe: 'response' })
+      .pipe(map((res) => {
+        const data = res.body;
+        // Log the raw response data
+        console.log('Raw API response:', JSON.stringify(data, null, 2));
+        return data;
+      }));
+  }
+
+  saveReceptionist(data:any): Observable<any> {
+    return this.http
+      .post<any>(`${this.apiUrl}/admin/receptionists`,data, { observe: 'response' })
+      .pipe(map((res) => res.body));
+  }
+
+  getReceptionistData(id:any): Observable<any> {
+    return this.http
+      .get<any>(`${this.apiUrl}/admin/receptionists/${id}`, { observe: 'response' })
+      .pipe(map((res) => res.body));
+  }
+
+  updateReceptionistData(id:any, data:any): Observable<any> {
+    return this.http
+      .put<any>(`${this.apiUrl}/admin/receptionists/${id}`,data, { observe: 'response' })
+      .pipe(map((res) => res.body));
+  }
+
+  deleteReceptionist(id:any): Observable<any> {
+    return this.http
+      .delete<any>(`${this.apiUrl}/admin/receptionists/${id}`, { observe: 'response' })
+      .pipe(map((res) => res.body));
+  }
+
+  deleteAllReceptionists(): Observable<any> {
+    return this.http
+      .delete<any>(`${this.apiUrl}/admin/receptionists`, { observe: 'response' })
+      .pipe(map((res) => res.body));
+  }
+}

